      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 발송과 스케줄러 실행의 흐름 안에서 잠금을 적용한 위치를 구체적으로 짚어, 어느 작업 범위를 잠금으로 보호했는지 알 수 있게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 실행 전에 잠금을 둔다는 일반적인 수준으로 설명하지만, 알림 발송 흐름에서 실제 적용한 지점이나 보호 범위는 분명하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송을 잠금으로 고쳤다는 사실만 반복하거나 로그 추적 이야기만 하고, 잠금을 적용한 지점은 제시하지 않는다."
          ]
        }
      }
    }
  ]
}

