{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 진통제 처방을 바로 수행하지 않고 투약을 멈춰 확인해야 한다고 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 용량이 평소 용량의 두 배로 처방된 상황",
          "task": "해당 처방을 그대로 수행해도 되는지 판단해야 했던 시점",
          "action": "처방 용량을 의심하게 된 비교 대상이나 당시 확인한 정보를 중심으로 투약 중단 판단의 근거 설명",
          "result": "그 근거가 담당의 확인 전까지 투약을 보류한다는 판단으로 이어졌음을 정리"
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의 확인이 필요하다고 판단한 구체적인 근거",
          "처방 용량의 이상 여부를 판단할 때 실제로 비교한 대상",
          "단순히 평소와 다르다는 인상을 넘어 확인이 필요하다고 본 당시 정보"
        ]
      },
      "question": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방됐던 때, 투약을 멈추고 담당의에게 확인해야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 짚고 본인이 내린 판단을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방을 의심한 이유를 실제 비교 대상이나 당시 확인한 정보로 구체화해, 담당의 확인 전 투약을 멈춰야 했던 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 용량이 평소의 두 배였다는 사실이나 의심스러운 처방은 확인해야 한다는 일반 원칙만 제시한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 멈춘 판단의 근거를 제시하지 않거나, 처방 오류를 바로잡은 결과 등 다른 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "수술 후 환자의 통증 변화를 이전 상태와 구분할 수 있도록 간호 기록에 담은 정보를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 통증을 관찰하고 간호 기록을 작성하던 업무",
          "task": "이전 관찰과 달라진 환자 상태가 기록에 드러나게 하는 것",
          "action": "상태의 차이를 보여 주기 위해 실제 기록에 포함한 정보를 구체적인 예로 설명",
          "result": "기록에서 이전 상태와 이후 상태의 차이를 파악할 수 있었는지 정리"
        },
        "expectedEvidence": [
          "이전 관찰과 달라진 통증 상태를 보여 주기 위해 실제 기록에 담은 정보",
          "관찰 시점이나 통증 정도 등 변화의 비교를 구체화하는 기록 예시"
        ]
      },
      "question": "정형외과 병동에서 수술 후 환자의 통증을 기록할 때, 이전 관찰과 달라진 환자 상태를 구분해 보여 주는 정보로 무엇을 남기셨나요?",
      "answerTip": "여러 일을 나열하기보다 한 환자의 사례를 떠올려 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "통증 간호 기록에 담은 정보를 관찰 시점별 통증 정도나 양상의 차이 등 실제 예시로 구체화해, 이전 상태와 무엇이 달랐는지 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "통증 정도나 환자 상태를 정확히 기록했다는 일반적인 설명에 머물러, 이전 상태와의 차이를 보여 주는 기록 정보가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "통증 변화에 관해 기록한 정보를 제시하지 않거나, 투약 수행이나 퇴원 교육 등 다른 업무만 설명한다."
          ]
        }
      }
    }
  ]
